<?php
function coverageLeaves(PDO$p,string$root):array{$seen=[];$result=[];$walk=function(string$id)use(&$walk,&$seen,&$result,$p){if(isset($seen[$id]))return;$seen[$id]=1;$q=$p->prepare("SELECT target_document_id FROM requirement_document_links WHERE source_document_id=? AND link_type='parent_of'");$q->execute([$id]);$children=$q->fetchAll(PDO::FETCH_COLUMN);if(!$children){$result[]=$id;return;}foreach($children as$c)$walk($c);};$walk($root);return array_values(array_unique($result));}
function coverageParents(PDO$p,string$id):array{$seen=[];$queue=[$id];$q=$p->prepare("SELECT source_document_id FROM requirement_document_links WHERE target_document_id=? AND link_type='parent_of'");while($queue){$x=array_shift($queue);$q->execute([$x]);foreach($q->fetchAll(PDO::FETCH_COLUMN)as$parent)if(!isset($seen[$parent])){$seen[$parent]=1;$queue[]=$parent;}}return array_keys($seen);}
function coverageCalculate(PDO$p,string$id):array{$q=$p->prepare('SELECT revision FROM requirement_documents WHERE id=?');$q->execute([$id]);$revision=$q->fetchColumn();if($revision===false)throw new RuntimeException('Dokument nicht gefunden.');$leafIds=coverageLeaves($p,$id)?:[$id];$s=['leaf_count'=>count($leafIds),'covered_count'=>0,'executed_count'=>0,'passed_count'=>0,'failed_count'=>0,'blocked_count'=>0,'outdated_count'=>0];foreach($leafIds as$leaf){$d=$p->prepare('SELECT revision FROM requirement_documents WHERE id=?');$d->execute([$leaf]);$leafRev=(int)$d->fetchColumn();$t=$p->prepare('SELECT result,document_revision FROM document_test_links WHERE document_id=? ORDER BY executed_at DESC,updated_at DESC');$t->execute([$leaf]);$rows=$t->fetchAll(PDO::FETCH_ASSOC);if(!$rows)continue;$s['covered_count']++;$valid=array_values(array_filter($rows,fn($r)=>(int)$r['document_revision']===$leafRev));if(!$valid){$s['outdated_count']++;continue;}$results=array_column($valid,'result');if(array_filter($results,fn($r)=>$r!=='not_run'))$s['executed_count']++;if(in_array('failed',$results,true))$s['failed_count']++;elseif(in_array('blocked',$results,true))$s['blocked_count']++;elseif(in_array('passed',$results,true))$s['passed_count']++;}$n=max(1,$s['leaf_count']);$s['test_coverage_percent']=round($s['covered_count']/$n*100,2);$s['coverage_percent']=round($s['executed_count']/$n*100,2);$s['passed_percent']=round($s['passed_count']/$n*100,2);if($s['outdated_count'])$status='Outdated';elseif($s['failed_count'])$status='Failed';elseif($s['passed_count']===$s['leaf_count'])$status='Passed';elseif($s['covered_count']===0)$status='Not Covered';else$status='Partial';$s['verification_status']=$status;$s['revision']=(int)$revision;$up=$p->prepare('INSERT INTO document_verification_snapshots(document_id,revision,leaf_count,covered_count,executed_count,passed_count,failed_count,blocked_count,outdated_count,coverage_percent,passed_percent,verification_status)VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE revision=VALUES(revision),leaf_count=VALUES(leaf_count),covered_count=VALUES(covered_count),executed_count=VALUES(executed_count),passed_count=VALUES(passed_count),failed_count=VALUES(failed_count),blocked_count=VALUES(blocked_count),outdated_count=VALUES(outdated_count),coverage_percent=VALUES(coverage_percent),passed_percent=VALUES(passed_percent),verification_status=VALUES(verification_status)');$up->execute([$id,$s['revision'],$s['leaf_count'],$s['covered_count'],$s['executed_count'],$s['passed_count'],$s['failed_count'],$s['blocked_count'],$s['outdated_count'],$s['coverage_percent'],$s['passed_percent'],$status]);return$s;}
function coverageRecalculateChain(PDO$p,string$id):void{coverageCalculate($p,$id);foreach(coverageParents($p,$id)as$parent)coverageCalculate($p,$parent);}
